@startuml

class User {
  + Id : string
}

class Doctor extends User {
  + CreateSchedule()
}

class Patient extends User {
  + CreateAppointment()
}

class Office {
  + Id : string
  + Name : string
}

class Schedule {
  + Id : string
  + StartDate : date
  + EndDate : date
}

class Appointment {
  + Id : string
  + StartDate : datetime
  + EndDate : datetime
}

class BloodTest extends Appointment {}

class Consultation extends Appointment {}

class Surgery extends Appointment {}

Doctor "1..*" -- "1..*" Office : applies to
Doctor "1" -- "*" Schedule : creates
Office "1" -- "*" Schedule : has
Patient "1" -- "*" Appointment : books
Schedule "1" -- "*" Appointment : includes

@enduml

